test.method_source:
@Test(expected = Exception.class)
    public void testGetInitialDomain_DivisionByZero() throws Exception {
        // If ddf = 2.0, d / (d - 2.0) results in Infinity (Double precision behavior)
        // Or if ddf is very close to 2, it results in very large numbers.
        // This tests the behavior of the math when d-2.0 is 0.
        double ddf = 2.0;
        FDistributionImpl fDist = new FDistributionImpl(5.0, ddf);

        double actual = invokeGetInitialDomain(fDist, 0.5);

        // In Java, double division by zero results in Infinity, not an Exception.
        // We check if it returns Infinity.
        Assert.assertTrue(Double.isInfinite(actual));
    }

