@Test
    public void testInterfaceRefinement() {
        // Test the path where baseType.isInterface() is true
        JavaType baseType = typeFactory.constructSimpleType(Collection.class, null);
        // Use a subclass that is not in the "shortcut" list to force refinement
        // LinkedList is in shortcut, so let's try to find one that isn't or just trigger the fallback
        // Actually, since LinkedList is in the shortcut, let's use a more complex scenario.

        // If we use a Map interface and a custom Map implementation
