public static double factorialDouble(final int n) {
        if (n < 0) {
            throw MathRuntimeException.createIllegalArgumentException(
                  "must have n >= 0 for n!, got n = {0}",
                  n);
        }
        if (n < 21) {
            return factorial(n);
        }
        return Math.floor(Math.exp(factorialLog(n)) + 0.5);
    }

test.method_source:
@Test
    public void testFactorialDouble_LargeN() {
        // Test values in the n >= 21 branch (using exp(factorialLog(n)))
        // 21! is approx 5.109094217170944e+19
        double n21 = MathUtils.factorialDouble(21);
        assertTrue(n21 > 0);

        // Check 25!
        // 25! = 15511210043330985984000000
        double expected25 = 1.5511210043330986E25;
        assertEquals(expected25, MathUtils.factorialDouble(25), expected25 * 1e-15);
    }

impl:
protected double calculateNumericalVariance() {
        final double N = getPopulationSize();
        final double m = getNumberOfSuccesses();
        final double n = getSampleSize();
        return (n * m * (N - n) * (N - m)) / (N * N * (N - 1));
    }

