        tais.getNextTarEntry();

        byte[] existingBuf = new byte[]{1, 2, 3};
        setInternalField(tais, "readBuf", existingBuf);
        setInternalField(tais, "entryOffset", 0);
        setInternalField(tais, "entrySize", 10);

