@Test
    public void testVerifyCheckSum_NegativeBytes() {
        // Test signedSum vs unsignedSum
        // If we have a byte 0xFF (-1)
        // unsignedSum adds 255, signedSum adds -1.
        byte[] header = new byte[200];
        for(int i=0; i<200; i++) header[i] = 0; // all zeros
        // unsignedSum = 0, signedSum = 0, storedSum = 0.
        // 0 == 0 is true.
        assertTrue(TarUtils.verifyCheckSum(header));

        // Put a negative byte
        header[0] = (byte) 0xFF; 
        // unsignedSum = 255, signedSum = -1, storedSum = 0.
        // 0 == 255 (F) || 0 == -1 (F) || 0 > 255 (F) -> false.
        assertFalse(TarUtils.verifyCheckSum(header));
    }

